def w(i, thema, f, li, q=None, korr=None):
    d = dict(id=f'r1-w{i}', nr=f'W{i}', thema=thema, f=f, a=[dict(li=li)], q=q or [('R1W', 1)])
    if korr:
        d['korr'] = korr
    return d


